const input = $('Subworkflow Input').first().json || {};
const state = input.state || input;
const directory = items[0]?.json || {};
const rows = Array.isArray(directory) ? directory : Object.values(directory);
const now = new Date().toISOString();
const companyName = state.inputs?.company_name || input.company_name || '';
const tickerInput = state.inputs?.ticker || input.ticker || '';
function norm(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}
const nameNorm = norm(companyName);
const tickerNorm = norm(tickerInput);
function score(row) {
  const title = row.title || row.name || '';
  const ticker = row.ticker || '';
  const titleNorm = norm(title);
  const rowTickerNorm = norm(ticker);
  let points = 0;
  if (tickerNorm && rowTickerNorm === tickerNorm) points += 120;
  if (titleNorm === nameNorm) points += 100;
  if (nameNorm && titleNorm.startsWith(nameNorm)) points += 70;
  if (nameNorm && titleNorm.includes(nameNorm)) points += 45;
  if (tickerNorm && rowTickerNorm.includes(tickerNorm)) points += 20;
  return points;
}
const ranked = rows
  .filter((row) => row && (row.title || row.name) && (row.cik_str || row.cik))
  .map((row) => ({ row, score: score(row) }))
  .filter((entry) => entry.score > 0)
  .sort((a, b) => b.score - a.score);
const best = ranked[0]?.row || null;
const rawCik = best?.cik_str || best?.cik || null;
const cik = rawCik ? String(rawCik).replace(/\D/g, '').padStart(10, '0') : null;
state.entity = {
  legal_name: best?.title || companyName || null,
  ticker: best?.ticker || tickerInput || null,
  cik,
  exchange: null,
  fiscal_year_end: null,
  reporting_currency: 'USD',
  is_public: Boolean(cik),
  confidence: cik && ranked[0].score >= 80 ? 'HIGH' : (cik ? 'MEDIUM' : 'LOW'),
  sources: [{ source_name: 'SEC Company Tickers Directory', source_url: 'https://www.sec.gov/files/company_tickers.json', source_date: now, confidence: cik ? 'HIGH' : 'LOW' }]
};
state.agent_status = state.agent_status || {};
state.agent_status.entity = cik ? 'resolved_public_company' : 'private_or_unresolved_public_company';
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_ENTITY', status: cik ? 'OK' : 'WARN', message: cik ? `Resolved ${state.entity.legal_name} with CIK ${cik}.` : 'No SEC public-company match; route to private/public-web research.' });
return [{ json: state }];

